llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Absolute oral bioavailability of meperidine in six normal young men was 47–73% after oral solution versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Absolute oral bioavailability of samidorphan was 69% in healthy male volunteers after a 2 mg oral dose versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Absolute oral bioavailability of meptazinol in male volunteers was 8.69 ± 1.61% after a 200 mg oral dose versus IV, arguing against F ≥ 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer molecules with direct absolute oral bioavailability measurements in healthy or normal subjects support F ≥ 20%, with values such as 47–73%, 69%, and 80–81%. Two high-transfer molecules show low oral bioavailability (about 8.7% and 18%), but the overall condition-matched evidence favors high bioavailability.",
  "evidence_gaps": [
    "Molecule 7 groups records for different compounds (brigatinib versus GSK1322322), creating a provenance conflict that prevents reliable use.",
    "Molecule 9 provides only qualitative 'good' bioavailability without a numeric F value, so it is not threshold-relevant.",
    "Some positive molecules have wide individual ranges that dip below 20% despite mean or central values above threshold, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

